import json

def check_input(bundle):
    return []

def render_input(bundle):
    return json.dumps(bundle)

def check_output(parsed, bundle):
    import cog_core
    problems = []
    actions = parsed.get('actions')
    if not isinstance(actions, list):
        return problems
    if parsed.get('abstained') and actions:
        problems.append(cog_core.problem('abstention', 'Abstention must have no actions.'))
    if not parsed.get('abstained') and not actions:
        problems.append(cog_core.problem('abstention', 'No actions requires abstention.'))
    notes = bundle.get('notes', '')
    for action in actions:
        if not isinstance(action, dict):
            continue
        quote = action.get('quote')
        if not isinstance(quote, str) or not quote or quote not in notes:
            problems.append(cog_core.problem('grounding', 'Quote must occur in supplied notes.'))
    return problems

import unittest
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'src'))
import task_logic

class ActionChecks(unittest.TestCase):
    def test_grounded(self):
        self.assertEqual(task_logic.check_output({'abstained': False, 'actions': [{'action': 'Send agenda', 'quote': 'Sam will send the agenda.'}]}, {'notes': 'Sam will send the agenda.'}), [])
    def test_invented_quote(self):
        self.assertTrue(task_logic.check_output({'abstained': False, 'actions': [{'action': 'Send agenda', 'quote': 'invented'}]}, {'notes': 'No actions.'}))
    def test_abstention(self):
        self.assertEqual(task_logic.check_output({'abstained': True, 'actions': []}, {'notes': 'No actions.'}), [])
